#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdint>
using namespace std;

int main() {
    int64_t n, k, y, p = 0;
    vector<int64_t> a;
    int64_t t;

    cin >> n >> k;
    for (y = 0; y < n; ++y) {
        cin >> t;
        if (t <= k)
            a.push_back(t);
    }

    sort(a.begin(), a.end());

    if (a.empty()) {
        cout << (k == 0 ? k : k - 1) << endl;
        return 0;
    }

    if (k == 0) {
        if (a[0] != 0)
            cout << k << endl;
        else
            cout << k + 1 << endl;
        return 0;
    }

    if (a[0] != 0) {
        if (a.size() > 1) {
            if (k >= 0 && k <= a[1]) {
                cout << k - 1 << endl;
                return 0;
            } else {
                p += a[1];
            }
        } else {
            if (k < a[0])
                cout << k - 1 << endl;
            else if (k == a[0])
                cout << k << endl;
            else
                cout << k - 1 << endl;
            return 0;
        }
    }

    for (size_t i = 1; i + 1 < a.size(); ++i) {
        if (a[i] == k) {
            cout << p + 1 << endl;
            return 0;
        }
        if (a[i] != a[i + 1] - 1) {
            if (k >= a[i] && k <= a[i + 1]) {
                cout << k - a[i] - 1 << endl;
                return 0;
            } else {
                p += a[i + 1] - a[i] - 1;
            }
        }
    }

    if (k > a.back())
        cout << k - a.back() - 1 << endl;
    else if (k == a.back())
        cout << p + 1 << endl;

    return 0;
}

